window.DAILY_ISSUE_2026_11_22 = [{"id": "https://www.archdaily.com/1188973/ca-la-tecla-renovation-hiha-studio", "title": "1572년의 골조를 품은 집, 카 라 테클라 리노베이션", "original_title": "Ca la Tecla Renovation / Hiha Studio", "url": "https://www.archdaily.com/1188973/ca-la-tecla-renovation-hiha-studio", "image_url": "https://images.adsttc.com/media/images/6afd/b8d1/eabd/2a00/0193/1d05/large_jpg/001.jpg?1795012843", "video_url": "", "has_video": false, "snippet": "스페인 산 쿠가트 세스가루게스에 위치한 카 라 테클라 건물은 1572년부터 여러 세대를 거치며 변형을 겪었다. 히하 스튜디오(Hiha Studio)는 240제곱미터 규모의 이 유적 같은 공간을 현대적인 주거 인테리어로 개조했다. 폴 빌라도무스(Pol Viladoms)가 사진을 기록했다.", "genre": "SPACE & ARCH", "source_name": "ArchDaily", "collected_at": "2026-11-22 04:40", "healed": true, "title_mt": "Ca la Tecla 리노베이션 / Hiha Studio", "deep": {"lens": "수세기의 흔적이 남은 뼈대에 현대적 재료를 얹어 시간의 층위를 시각화한다.", "why_now": "오래된 건물의 구조를 허물지 않고 시간의 레이어를 남겨 공간의 무게감을 확보하는 방식이 주목받는다.", "mechanism": "오랜 세월 동안 누적된 건축적 변형을 그대로 살리면서 실내를 주거 용도에 맞게 재편했다.", "sensory": "거친 옛 벽돌과 매끄러운 현대적 마감재가 대비되어 손끝에 닿는 물성의 차이가 선명하다.", "transfer": "역사적 건물의 내부를 촬영할 때, 세월이 묻어나는 벽면을 배경으로 두고 간결한 금속 조명을 배치해 시대를 대비시키는 샷으로 활용한다.", "context": "스페인 산 쿠가트 세스가루게스에서 진행된 이 프로젝트는 1572년부터 이어져 온 건물의 역사적 맥락을 다루며, 세르카믹 칼라프(Ceramica Calaf), 정(JUNG), 산타 앤 콜(Santa & Cole) 등의 제조사 자재가 사용되었다.", "keywords": ["리노베이션", "역사적건축", "스페인", "주거인테리어"], "evidence": "Records show that the building has existed since 1572. Over the centuries, the property has been occupied by different generations and family units, undergoing various transformations and adaptations to meet the needs of each period.", "kind": "프로젝트", "depth": 3, "grounding": "partial", "depth_reason": "1572년부터 이어진 오랜 건물의 리노베이션이라는 역사적 흥미 요소가 있으나 세부 설계 전략에 대한 설명이 부족하다.", "sources": [], "findings": []}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.sightunseen.com/2026/11/the-hits-from-this-years-collectible-new-york-fair/", "title": "컬렉터블 뉴욕이 포착한 동시대 디자인의 변주: 일상과 유희의 결합", "original_title": "The hits from this year’s Collectible New York fair", "url": "https://www.sightunseen.com/2026/11/the-hits-from-this-years-collectible-new-york-fair/", "image_url": "https://www.sightunseen.com/wordpress/wp-content/uploads/2026/11/COLLECTIBLE-4-728x569.jpg", "video_url": "", "has_video": false, "snippet": "어퍼 이스트 사이드의 옛 영화관에서 열린 컬렉터블 뉴욕(Collectible New York)은 디자인의 경계를 확장하는 실험적 오브제를 선보였다. 아이템 스튜디오(iitem studio)의 실크와 주물 철제 데이베드, 콘트라스트 프랙티스(Contrast Practice)의 스테인리스 스틸 수납장 등 기능과 조형 사이를 오가는 작업이 주목받았다. 디자이너가 스스로 갤러리스트가 되는 최근의 흐름 또한 이번 페어의 핵심적인 변화로 드러났다.", "genre": "CONTEMPORARY ART", "source_name": "Sight Unseen", "collected_at": "2026-11-22 04:41", "healed": true, "title_mt": "올해 컬렉터블 뉴욕(Collectible New York) 박람회의 인기 작품", "deep": {"lens": "일상의 도구를 비일상적 물성으로 재해석하여, 공간 내에서 오브제가 수행하는 유희적 기능을 강조한다.", "why_now": "디자인 갤러리 시스템에 의존하지 않고 디자이너가 자신의 작업과 동료의 작품을 직접 큐레이션하는 독립적 운영 모델이 확산하고 있다.", "mechanism": "체스 테이블과 같은 유희적 가구에 물소 뿔, 콘크리트 블록, 레진 등 이질적 재료를 결합하여 기능적 도구를 예술적 오브제로 전환한다.", "sensory": "스테인리스 스틸의 차가운 금속성, 실크와 양피지의 유연한 촉감, 그리고 5갤런 생수통을 숨기는 체리나무 널판의 단단한 질감이 대비를 이룬다.", "transfer": "콘티 연출 시, 일상의 평범한 사물(생수통, 전화선 등)을 금속이나 고급 목재 프레임으로 감싸 의외의 조형미를 끌어내는 디테일 샷을 활용하라.", "context": "컬렉터블 페어는 2018년 브뤼셀에서 시작되어 유럽 중심의 디자인 담론을 형성해왔으며, 오브젝트 오브 커먼 이벤츠(Objects of Common Interest) 등 실험적 스튜디오를 지속적으로 소개했다. 이번 뉴욕 에디션은 기존의 화이트 큐브를 벗어나 폐쇄된 영화관이라는 장소성을 활용해 공간의 레이어를 재구성했다.", "keywords": ["컬렉터블뉴욕", "오브제디자인", "공간큐레이션", "물성실험"], "evidence": "The fair’s former WSA headquarters but kind of delightful to experience as a New Yorker.", "kind": "뉴스·이슈", "depth": 3, "grounding": "partial", "depth_reason": "페어의 현장감과 주요 작품을 나열했으나, 개별 작업의 기법적 깊이보다는 트렌드 요약에 집중하고 있다.", "sources": [{"n": 3, "type": "공식·1차", "title": "Contrast Practice", "url": "https://us.list-manage.com/11etGkJQIy9?e=520da9f661&c2id=1295bae7a12bea27ac8ddfcce70dbe9a"}], "findings": [{"text": "콘트라스트 프랙티스는 수작업으로 제작된 가구를 선보이며, 일상적인 유지관리를 위해 극세사 천 사용을 권장한다.", "s": 3, "quote": "Do codziennego przecierania z drobnych zabrudzeń, takich jak ślady palców, wystarczy ściereczka z mikrofibry."}]}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.archdaily.com/1188720/lamberth-palace-arches-tigg-plus-coll-architects", "title": "철도 하부의 해체 가능한 목재 아치: 램버트 궁전 아치 재생", "original_title": "Lamberth Palace Arches / Tigg + Coll Architects", "url": "https://www.archdaily.com/1188720/lamberth-palace-arches-tigg-plus-coll-architects", "image_url": "https://images.adsttc.com/media/images/6afb/7c67/8074/f464/a9f9/3436/large_jpg/lamberth-palace-arches-tigg-plus-coll-architects_12.jpg?1794866572", "video_url": "", "has_video": false, "snippet": "티그 콜 아키텍츠(Tigg + Coll Architects)는 런던에서 가장 번잡한 철도 노선 아래 방치되었던 빅토리아 시대 철도 아치 3개를 공부와 휴식을 위한 공간으로 탈바꿈시켰다. 활성 철도 하부의 기술적 제약을 극복하기 위해 분해 가능한 대량 목재(Mass-timber) 구조 시스템을 개발하여 적용했다.", "genre": "SPACE & ARCH", "source_name": "ArchDaily", "collected_at": "2026-11-22 01:06", "healed": true, "title_mt": "램버트 궁전 아치 / Tigg + Coll Architects", "deep": {"lens": "진동하는 철도 하부에 영구 구조물 대신 해체 가능한 목재 골조를 끼워 넣어 유휴 부지를 공공 공간으로 바꾼다.", "why_now": "도시 내 과밀화 속에서 남겨진 하부 공간의 구조적 제약을 생태적 공법으로 돌파하는 정교한 공간 재활용 방식이다.", "mechanism": "활성 철도 노선에서 발생하는 진동과 소음을 고려하여 구조체에 무리를 주지 않는 분해 가능한 대량 목재 시스템을 조립했다.", "sensory": "거친 벽돌 곡면의 철도 아치 구조물 내부를 부드러운 목재 결이 감싸며 소음을 흡수하고 안온한 밀도를 만든다.", "transfer": "철도 하부나 교량 아래 로케이션 촬영 시, 임시 목재 가벽을 조립식으로 세워 진동을 흡수하는 공간 콘티에 적용한다.", "context": "티그 콜 아키텍츠는 런던의 도심 유휴 공간을 재활용하는 프로젝트를 다수 진행해 왔다.", "keywords": ["철도아치", "목재구조", "공간재생", "런던건축"], "evidence": "TiggColl has transformed three previously underutilised Victorian railway arches beneath one of London's busiest railway routes into new spaces for studying, socialising and relaxing, developing a demountable mass-timber system", "kind": "프로젝트", "depth": 3, "grounding": "partial", "depth_reason": "철도 아치를 목재로 재생한 구체적 사례이나 세부 기술적 수치가 부족하여 평이한 수준의 프로젝트 소개에 머문다.", "sources": [{"n": 1, "type": "위키백과", "title": "Lambeth Palace", "url": "https://en.wikipedia.org/wiki/Lambeth%20Palace"}], "findings": [{"text": "Lambeth Palace is the official London residence of the Archbishop of Canterbury.", "s": 1, "quote": "Lambeth Palace is the official London residence of the Archbishop of Canterbury."}]}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.dezeen.com/2026/11/20/dezeen-awards-white-house-dezeen-weekly-podcast/", "title": "2026 디진 어워즈가 짚어낸 디자인의 현재와 백악관 볼룸의 건축적 쟁점", "original_title": "The best designers in the world right now", "url": "https://www.dezeen.com/2026/11/20/dezeen-awards-white-house-dezeen-weekly-podcast/", "image_url": "https://static-2026.dezeen.com/uploads/2026/11/dezeen-weekly-podcast-20-november-2026-sq-1024x1024.jpg", "video_url": "", "has_video": false, "snippet": "건축·디자인 매체 디진(Dezeen)이 2026년 디진 어워즈 수상작을 발표하며 올해의 주요 디자인 흐름을 정리했다. 이와 함께 도널드 트럼프 전 대통령의 백악관 볼룸 프로젝트가 구체화됨에 따라 발생하는 건축적·정치적 논란을 다뤘다. 팟캐스트를 통해 저널리스트들이 어워즈 수상작의 선정 이유와 백악관 증축안의 사회적 파장을 논의한다.", "genre": "SPACE & ARCH", "source_name": "Dezeen", "collected_at": "2026-11-22 01:06", "healed": true, "title_mt": "현재 세계 최고의 디자이너", "deep": {"lens": "매체가 선정한 어워즈 수상작은 당대 크리에이티브의 기준을, 백악관 볼룸 프로젝트는 권력이 공간을 점유하는 방식의 갈등을 드러낸다.", "why_now": "디자인 어워즈의 결과는 동시대 공간 설계의 지향점을 보여주며, 백악관 볼룸은 건축이 정치적 의사결정과 어떻게 충돌하는지 보여주는 사례다.", "mechanism": "팟캐스트 형식으로 어워즈의 심사 과정과 백악관 볼룸의 물리적 실체를 대조하며 건축적 이슈를 다각도로 분석한다.", "sensory": "건축물의 물리적 형태가 구체화될 때 발생하는 도시적·사회적 마찰음과 공간의 상징성이 지닌 무게감을 다룬다.", "transfer": "공간의 물리적 변경이 가져오는 사회적 파장을 콘티 설계 시 고려 요소로 삼고, 권위적 공간의 재구성이 초래할 시각적·정치적 논란을 연출의 서사로 활용한다.", "context": "디진은 런던과 뉴욕, 상하이에 거점을 둔 건축·디자인 매체로 매주 팟캐스트를 통해 주요 이슈를 전달한다. 디진 어워즈 2026은 건축 부문 152개 후보작을 선정하며 디자인의 미래 방향성을 지속적으로 타진해왔다.", "keywords": ["디진어워즈", "건축담론", "공간정치", "백악관볼룸"], "evidence": "This week, the Dezeen Awards winners for 2026 were unveiled.", "kind": "뉴스·이슈", "depth": 2, "grounding": "partial", "depth_reason": "수상작의 구체적인 명단이나 백악관 볼룸의 상세 설계 정보가 원문에 포함되지 않아 분석의 깊이가 제한적이다.", "sources": [{"n": 1, "type": "공식·1차", "title": "Dezeen Weekly", "url": "https://podcasts.apple.com/us/podcast/dezeen-weekly/id1871205904"}, {"n": 2, "type": "위키백과", "title": "Dezeen", "url": "https://en.wikipedia.org/wiki/Dezeen"}, {"n": 4, "type": "RE:COLLECTION 과거 기사", "title": "디진 어워즈 2026 마스터 심사위원단이 던진 질문", "url": "https://www.dezeen.com/2026/09/24/dezeen-awards-2026-trimble-master-jury-video/"}, {"n": 5, "type": "RE:COLLECTION 과거 기사", "title": "디진 어워드 2026 건축 부문 최종 후보 152선 공개", "url": "https://www.dezeen.com/2026/09/21/dezeen-awards-2026-architecture-shortlist/"}], "findings": []}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://hyperallergic.com/hail-to-the-squash-king/", "title": "시장가와 서사 사이: 피터 브래들리와 하워데나 핀델의 캔버스가 증명하는 것", "original_title": "Hail to the Squash King", "url": "https://hyperallergic.com/hail-to-the-squash-king/", "image_url": "https://storage.ghost.io/c/51/f8/51f871d8-b6be-4a73-b958-0ca4fff0110a/content/images/2026/11/9F713BAA-9DB0-4B38-8668-724D4CE5430F_1_105_c.jpeg", "video_url": "", "has_video": false, "snippet": "피터 브래들리의 색면 추상과 하워데나 핀델의 점점이 박힌 캔버스를 가로지르며, 저자는 현대 미술 시장의 기이한 가치 평가와 일상의 단상을 교차시킨다. 힐마 아프 클린트의 기록적인 경매가와 대조되는 평범한 일상의 물가, 그리고 오리엔탈리즘을 해체하는 실험 영화의 서사를 통해 예술이 자본과 사회 속에서 작동하는 방식을 관찰한다.", "genre": "CONTEMPORARY ART", "source_name": "Hyperallergic", "collected_at": "2026-11-22 00:20", "healed": true, "title_mt": "스쿼시 킹에게 경의를 표합니다", "deep": {"lens": "예술 작품의 경매가와 일상의 소비재 가격을 나란히 배치해, 자본이 예술을 박제하는 방식과 그 이면의 불안을 동시에 드러낸다.", "why_now": "예술적 가치가 시장의 수치로 치환되는 속도가 빨라지는 가운데, 작가의 실천적 서사와 작품의 물성이 자본의 논리에 어떻게 저항할 수 있는지 묻는다.", "mechanism": "영화적 몽타주 기법처럼 상반된 이미지와 텍스트를 병치하여, 관람객이 스스로 가치의 간극을 인지하도록 유도한다.", "sensory": "색면의 밀도 높은 질감과 캔버스 위 점의 반복적인 리듬감이 빚어내는 시각적 긴장감이, 경매장의 건조한 숫자와 대비되어 물리적 무게를 환기한다.", "transfer": "콘티 구성 시, 고가의 예술 작품과 저렴한 일상 사물을 동일한 프레임에 담아 화면의 긴장감을 조성하고, 사운드 디자인으로 그 간극을 강조하는 연출을 제안한다.", "context": "피터 브래들리는 1971년 인종 통합 전시인 '더 럭스 쇼(The De Luxe Show)'를 기획한 이력이 있으며, 하워데나 핀델은 인종과 페미니즘 이슈를 다루는 혼합 매체 작가로 잘 알려져 있다. 힐마 아프 클린트는 최근 균류의 미학적 탐구와 함께 시대와 장르를 횡단하는 시각적 패턴의 선례로 재조명되고 있다.", "keywords": ["색면추상", "미술시장", "오리엔탈리즘", "물성", "자본의논리"], "evidence": "Hilma af Klint painting shatters records", "kind": "뉴스·이슈", "depth": 3, "grounding": "full", "depth_reason": "예술 시장의 현황과 비평적 시각을 다루었으나, 특정 작업의 구체적인 기법보다는 현상에 대한 관찰 위주로 서술되어 있다.", "sources": [{"n": 1, "type": "위키백과", "title": "Peter Bradley (artist)", "url": "https://en.wikipedia.org/wiki/Peter%20Bradley%20%28artist%29"}, {"n": 2, "type": "위키백과", "title": "Howardena Pindell", "url": "https://en.wikipedia.org/wiki/Howardena%20Pindell"}, {"n": 3, "type": "RE:COLLECTION 과거 기사", "title": "곰팡이의 시각적 계보: 파이돈이 엮은 균류의 미학적 탐구", "url": "https://www.thisiscolossal.com/2026/09/spanning-200-works-a-new-book-celebrates-the-world-of-fungi/"}], "findings": [{"text": "피터 브래들리는 1971년 휴스턴에서 인종 간 통합을 시도한 전시인 더 럭스 쇼를 기획했다.", "s": 1, "quote": "In 1971 while associate director of the Perls Galleries, Bradley curated The De Luxe Show under the auspices of the famed de Menil family in Houston, Texas, considered to be one of the early racially integrated art exhib"}, {"text": "하워데나 핀델은 A.I.R. 갤러리를 공동 설립하여 여성 예술가, 특히 흑인 여성의 권익을 옹호했다.", "s": 2, "quote": "She co-founded the A.I.R. Gallery and worked with other groups to advocate for herself and other female artists, Black women in particular."}]}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.dezeen.com/2026/11/21/zha-theatre-royal-de-rabat-morroco/", "title": "모로코 라바트 왕립 극장: 부레그레그 강변의 지형을 조각한 유선형 공연장", "original_title": "ZHA completes “secular” Théâtre Royal de Rabat in Morocco", "url": "https://www.dezeen.com/2026/11/21/zha-theatre-royal-de-rabat-morroco/", "image_url": "https://static-2026.dezeen.com/uploads/2026/11/theatre-royal-de-rabat-zha-architecture-morocco-cultural_dezeen_2364_sq-1024x1024.jpg", "video_url": "", "has_video": false, "snippet": "자하 하디드 아키텍츠(ZHA)가 모로코 라바트와 살레 사이 부레그레그 강변에 라바트 왕립 극장을 완공했다. 이 건축물은 1,821석의 메인 공연장, 250석의 스튜디오 극장, 7,000석 규모의 야외 원형 극장으로 구성된다. ZHA는 강변의 지형적 흐름을 유선형 외관에 반영하고, 내부에는 이슬람 전통 장식인 무카르나스를 현대적으로 재해석한 음향 벽면을 설치했다.", "genre": "SPACE & ARCH", "source_name": "Dezeen", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "ZHA, 모로코의 '세속적'인 라바트 왕립 극장(Théâtre Royal de Rabat) 완공", "deep": {"lens": "강변의 흐름을 잇는 유선형 외관과 무카르나스의 기하학적 입체감을 결합해, 전통 문법을 현대적 음향 장치로 치환한 공간이다.", "why_now": "디지털 설계의 정교함이 전통 장식의 기하학적 복잡성과 만날 때 발생하는 물리적 깊이를 확인해야 한다.", "mechanism": "메인 공연장 벽면은 무카르나스 구조를 데이터로 모델링하여 음향 반사를 최적화하는 다면체 패널로 구현했다.", "sensory": "흐르는 천처럼 얽힌 계단이 겹치는 3층 높이의 로비는 빛과 그림자의 깊이를 더하며, 크리스털처럼 각진 공연장 내벽은 소리의 입자를 시각화한다.", "transfer": "공연장이나 전시 공간 설계 시, 천장이나 벽면의 전통 패턴을 입체적인 다면체 구조로 변환하여 음향 반사판과 장식적 요소를 동시에 해결하는 방식을 적용할 수 있다.", "context": "ZHA가 아프리카 대륙에서 처음 완공한 프로젝트다. 자하 하디드는 생전 이 공간을 세속적이지만 관객을 상상의 시간과 공간으로 이동시키는 장소로 정의했다.", "keywords": ["자하하디드", "무카르나스", "지형순응", "음향설계", "공연장"], "evidence": "ZHA took visual cues from the riverbank site of this national theatre in Morocco when designing its sweeping exterior form", "kind": "프로젝트", "depth": 5, "grounding": "full", "depth_reason": "전통 장식인 무카르나스를 음향 최적화 다면체로 치환한 기법과 지형 순응적 외관 설계가 구체적으로 제시되어 실무적 적용 가치가 높다.", "sources": [{"n": 1, "type": "공식·1차", "title": "Global Architecture Studio | ZHA Architects", "url": "https://www.zha.com/"}, {"n": 2, "type": "위키백과", "title": "Zaha Hadid", "url": "https://en.wikipedia.org/wiki/Zaha%20Hadid"}, {"n": 3, "type": "위키백과", "title": "Mohammed VI Tower", "url": "https://en.wikipedia.org/wiki/Mohammed%20VI%20Tower"}], "findings": []}, "is_pick": true, "issue_date": "2026-11-22"}, {"id": "https://leibal.com/interiors/lannes/", "title": "파리 란(Lannes) 아파트, 장 긴스버그의 골조 위에 얹은 미니멀리즘의 물성", "original_title": "Lannes", "url": "https://leibal.com/interiors/lannes/", "image_url": "https://leibal.com/wp-content/uploads/2026/11/leibal_lannes_atelier-baptiste-legue_08.jpg", "video_url": "", "has_video": false, "snippet": "파리 기반의 아틀리에 밥티스트 르게(Atelier Baptiste Legué)가 장 긴스버그가 설계한 90제곱미터 규모 아파트를 개조했다. 모래와 석재 등 중성적인 색채와 질감을 바탕으로 모놀리식 주방 아일랜드와 세면대를 배치해 공간의 깊이감을 더했다. 빈티지 가구와 동시대 예술 작품을 조화롭게 배치하여 절제된 건축적 언어를 완성했다.", "genre": "SPACE & ARCH", "source_name": "Leibal", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "란", "deep": {"lens": "장 긴스버그의 견고한 골조를 배경 삼아, 석재와 흑색 목재라는 이질적 물성을 배치해 공간의 밀도를 조율하는 방식이 돋보인다.", "why_now": "디지털 피로도가 높은 환경에서 소재 본연의 촉각적 깊이를 강조하는 미니멀리즘이 주거 공간의 새로운 안식처로 주목받는다.", "mechanism": "모놀리식 형태의 석재 주방 아일랜드와 세면대를 공간의 중심에 두어 시각적 무게를 잡고, 얇은 커튼을 통과한 자연광으로 소재의 미세한 불균형을 드러낸다.", "sensory": "모래와 석재의 건조하고 차분한 질감이 흑색 목재의 묵직함과 대비되며, 빛이 머무는 벽면의 미세한 요철이 공간에 생동감을 부여한다.", "transfer": "광고 촬영 시 모노톤 배경에 텍스처가 강한 석재 오브제를 배치해 명암 대비를 극대화하고, 여백을 활용해 피사체의 형태적 독립성을 강조할 수 있다.", "context": "장 긴스버그가 설계한 기존 건축물의 구조적 뼈대를 유지하면서, 내부는 아틀리에 밥티스트 르게의 미니멀리즘 해석을 통해 새로운 시간의 레이어를 얹었다.", "keywords": ["미니멀리즘", "아틀리에밥티스트르게", "파리인테리어", "물성", "모놀리식"], "evidence": "Stone also takes on a more sculptural presence in the form of a monolithic kitchen island and a washbasin in the bathroom", "kind": "프로젝트", "depth": 3, "grounding": "partial", "depth_reason": "건축적 골조와 물성의 대비라는 명확한 시각적 장치를 제시하나, 기존 건축물에 대한 심층적인 분석 정보가 부족하다.", "sources": [], "findings": []}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://leibal.com/interiors/dkr-house/", "title": "폴란드 비스와 계곡, 그을린 목재로 빚은 안식처 DKR 하우스", "original_title": "DKR House", "url": "https://leibal.com/interiors/dkr-house/", "image_url": "https://leibal.com/wp-content/uploads/2026/11/leibal-dkr-house-oskar-firek-architects-1515.jpg", "video_url": "", "has_video": false, "snippet": "오스카 파이렉 아키텍츠(Oskar Firek Architects)가 폴란드 크라쿠프 인근 비스와 계곡에 설계한 주택이다. 경사지를 활용해 3개 층으로 구성했으며, 외관의 검게 그을린 목재를 실내의 짙은 오크 목공으로 이어지게 연출했다. 점토 미장, 화강암, 나이카 규암 등 절제된 재료를 사용해 거주자를 위한 휴식 공간을 완성했다.", "genre": "SPACE & ARCH", "source_name": "Leibal", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "DKR 하우스", "deep": {"lens": "외피의 거친 탄화 목재를 실내 가구의 정교한 목공으로 치환하며, 외부의 자연적 질감을 주거의 내밀한 일상으로 자연스럽게 전이시킨다.", "why_now": "디지털 과잉 시대에 점토, 석재, 고목 등 물리적 무게감이 확실한 재료를 조합해 주거의 원초적 안식 기능을 회복하려는 흐름을 보여준다.", "mechanism": "비스와 계곡의 경사지를 이용해 최하층을 지면 아래로 숨기고, 지상층에는 층고를 높인 거실을 배치해 숲과 테라스가 시각적으로 연결되도록 설계했다.", "sensory": "점토 미장의 매트한 질감이 창으로 들어오는 빛을 부드럽게 산란시키며, 수 세기 동안 물속에 잠겨 있던 흑색 오크 식탁의 묵직한 물성이 공간의 중심을 잡는다.", "transfer": "공간의 외장재를 실내 가구의 마감재로 동일하게 가져가는 '재료의 연속성' 기법을 활용해, 카메라 앵글이 내외부를 넘나들 때 시각적 통일감을 극대화한다.", "context": "오스카 파이렉 아키텍츠는 2020년 프로젝트에 합류하여 기존 건축 평면을 바탕으로 벽체 위치와 동선, 가구 배치를 재구성했다.", "keywords": ["탄화목재", "비스와계곡", "점토미장", "오크가구"], "evidence": "The burned black timber on the exterior of DKR House reappears inside as dark-stained oak", "kind": "프로젝트", "depth": 3, "grounding": "full", "depth_reason": "재료의 연속성을 활용한 공간 구성은 명확하나, 구조적 혁신보다는 감각적 마감과 가구 큐레이션에 집중된 사례다.", "sources": [], "findings": []}, "is_pick": true, "issue_date": "2026-11-22"}, {"id": "https://leibal.com/interiors/koko/", "title": "시간표 없는 피트니스 스튜디오, 문턱을 지우고 빛을 들이다", "original_title": "koko", "url": "https://leibal.com/interiors/koko/", "image_url": "https://leibal.com/wp-content/uploads/2026/11/leibal-koko-lawsonware-180.jpg", "video_url": "", "has_video": false, "snippet": "호주 센트럴코스트 에리나에 위치한 운동 및 회복 스튜디오 코코는 정해진 수업 시간표 없이 24시간 자율적으로 운영된다. 디자이너 로슨 웨어는 쇼지 스크린과 광목 노렌으로 공간을 구획하고, 재활용 목재와 마감 없는 시멘트 바닥을 사용하여 사용감과 시간이 쌓이는 인테리어를 완성했다.", "genre": "SPACE & ARCH", "source_name": "Leibal", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "코코", "deep": {"lens": "정해진 시간표를 없앤 운동 공간은 문 대신 천과 빛으로 구역을 가른다.", "why_now": "디지털 피로 속에서 단단한 물질성과 아날로그적 동선 설계가 상업 공간의 새로운 기준이 된다.", "mechanism": "쇼지 스크린과 이사무 노구치의 아카리 조명이 빛을 부드럽게 산란시켜 서로 다른 구역을 하나의 결로 묶는다.", "sensory": "거친 시멘트 바닥과 이미 흠집 난 재활용 목재가 맨발의 감촉과 시간의 무게를 그대로 전달한다.", "transfer": "공간 콘티에서 문과 벽을 없애고 광목 노렌과 레진 조명을 활용해 시선이 부드럽게 이어지는 롱테이크 샷을 구성한다.", "context": "인테리어 스튜디오 로슨 웨어는 호주 서던하이랜즈를 기반으로 우아하고 시대를 초월하는 공간을 만든다.", "keywords": ["상업인테리어", "공간설계", "재활용목재", "빛의산란"], "evidence": "There is no class timetable at koko. Members use the reformers, the weights and the recovery room on demand", "kind": "프로젝트", "depth": 3, "grounding": "full", "depth_reason": "온디맨드 운영 방식에 맞춘 공간 구획과 재료 선택이 돋보이나 선례를 뒤흔드는 파격까지는 이르지 않는다.", "sources": [{"n": 1, "type": "공식·1차", "title": "Lawson Ware Interior Design | Southern Highlands", "url": "http://lawsonware.com.au/"}, {"n": 2, "type": "공식·1차", "title": "koko | reformer pilates, sauna, cold plunge, Erina, Central Coast", "url": "http://kokostudio.com.au/"}, {"n": 3, "type": "위키백과", "title": "Isamu Noguchi", "url": "https://en.wikipedia.org/wiki/Isamu%20Noguchi"}], "findings": [{"text": "로슨 웨어는 알릭스 로슨과 제시카 웨어가 이끄는 서던하이랜즈 기반의 인테리어 디자인 스튜디오다.", "s": 1, "quote": "Lawson Ware is an interior design practice based in the Southern Highlands, led by Alix Lawson and Jessica Ware."}, {"text": "코코 스튜디오는 리포머와 웨이트 공간이 24시간 상시 개방된다.", "s": 2, "quote": "Reformer and strength are open 24/7, and the sauna and cold plunge can be booked during staffed hours."}, {"text": "이사무 노구치는 1920년대부터 여섯 시대에 걸쳐 활동한 미국의 조각가이자 가구 디자이너다.", "s": 3, "quote": "Isamu Noguchi (...) was an American artist, furniture designer and landscape architect whose career spanned six decades from the 1920s."}]}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://leibal.com/interiors/minimalist-house/", "title": "시가현의 1인 주거, 보이드와 유리 복도로 확장된 일상의 리듬", "original_title": "Minimalist House", "url": "https://leibal.com/interiors/minimalist-house/", "image_url": "https://leibal.com/wp-content/uploads/2026/11/leibal-minimalist-house-form-kouichi-kimura-architects-1521.jpg", "video_url": "", "has_video": false, "snippet": "폼/고이치 기무라 아키텍츠(FORM/Kouichi Kimura Architects)가 일본 시가현 호숫가 언덕에 73제곱미터 규모의 1인 가구 주택을 설계했다. 본채와 별채를 유리 복도로 연결해 이동 동선마다 자연을 마주하게 했으며, 내부에는 파티션 대신 층고와 바닥 높낮이 차이를 활용해 생활 영역을 구분했다.", "genre": "SPACE & ARCH", "source_name": "Leibal", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "미니멀리즘 주택", "deep": {"lens": "거주자의 일상 리듬을 건축의 골격으로 치환하여, 물리적 면적을 넘어선 시각적 확장과 계절의 변화를 내부로 투영하는 공간 설계다.", "why_now": "가족 중심의 주거 문법에서 벗어나, 1인 가구의 실제 행위와 감각에 집중한 공간의 재구성이 요구되는 시점이다.", "mechanism": "본채와 별채 사이의 보이드와 유리 복도는 시선을 호수로 관통시키며, 이동하는 행위 자체를 외부 기후와 빛을 경험하는 전이 공간으로 전환한다.", "sensory": "높은 층고를 가진 거실의 벽면은 음악의 울림을 증폭시키며, 좁고 높은 창을 통해 유입된 빛이 시간에 따라 벽과 바닥 위로 길게 그림자를 드리운다.", "transfer": "공간 내 파티션을 제거하고 층고 변화와 보이드만으로 영역을 분할하는 방식을 채택해, 좁은 로케이션에서도 깊이감을 만드는 샷을 구성할 수 있다.", "context": "폼/고이치 기무라 아키텍츠는 일본 시가현을 중심으로 골판지 금속과 검은색 마감재를 활용한 미니멀리즘 건축을 지속해왔다. 이번 작업은 기존의 73제곱미터 규모 주택 프로젝트와 맥락을 같이하며, 거주자의 시선을 조율하여 작은 공간을 압도적으로 확장하는 실험을 이어간다.", "keywords": ["미니멀리즘", "보이드", "공간확장", "시가현", "1인주거"], "evidence": "The corridor acts as a threshold zone, glazed on both sides, so the routine walk to wash or shower passes through daylight, breeze, and the current season on the hillside.", "kind": "프로젝트", "depth": 4, "grounding": "full", "depth_reason": "1인 가구의 동선을 건축적 전이 공간으로 해석한 논리가 명확하며, 재료와 구조적 장치가 구체적으로 제시됨.", "sources": [{"n": 1, "type": "RE:COLLECTION 과거 기사", "title": "시가현의 미니멀리스트 하우스, 1인 가구를 위한 거대한 보이드", "url": "https://www.dezeen.com/2026/10/29/minimalist-house-form-kouichi-kimura/"}, {"n": 2, "type": "RE:COLLECTION 과거 기사", "title": "시가현의 미니멀리스트 하우스, 1인 가구를 위한 거대한 보이드", "url": "https://www.archdaily.com/1186735/minimalist-house-form-kouichi-kimura-architects"}], "findings": []}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://leibal.com/furniture/moname-tables/", "title": "건축가의 도면을 가구로 번역하는 방식, 모남(Monâme)", "original_title": "Monâme Tables", "url": "https://leibal.com/furniture/moname-tables/", "image_url": "https://leibal.com/wp-content/uploads/2026/11/leibal-moname-merckx-holvoet-simon-de-burbure-0.jpg", "video_url": "", "has_video": false, "snippet": "벨기에의 건축 스튜디오 메르크스홀보에(Merckx-Holvoet)와 건축가 시몬 드 부르뷔르(Simon de Burbure)가 협업하여 가구 브랜드 모남을 론칭했다. 이들은 건축가가 설계한 테이블을 브랜드의 핵심으로 삼으며, 모든 제작 공정을 벨기에 내에서 수작업 파티나 마감으로 완성한다. 건축가의 고유한 서명을 담은 가구는 일회성 소비가 아닌 공간의 중심을 잡는 오브제로 기능한다.", "genre": "SPACE & ARCH", "source_name": "Leibal", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "Monâme 테이블", "deep": {"lens": "건축가의 설계를 가구라는 작은 스케일로 압축할 때, 균일한 코팅 대신 수작업 파티나를 입혀 재료의 비정형성을 확보한다.", "why_now": "디지털로 평평하게 다듬어진 가구 시장에서, 건축가의 의도가 담긴 물리적 무게와 시간의 흔적이 묻어나는 물성에 대한 수요가 높아지고 있다.", "mechanism": "스프레이 코팅을 배제하고 수작업으로 파티나를 덧입혀, 표면의 불균일한 톤을 유도함으로써 빛의 산란과 시간의 층위를 시각화한다.", "sensory": "손으로 빚은 듯한 파티나 마감의 거친 질감과 견고한 목재의 무게감이 결합되어, 정형화된 공산품과는 다른 깊은 물질적 밀도를 전달한다.", "transfer": "공간 연출 시 가구의 표면을 조명 아래 배치하여 파티나의 미세한 톤 차이를 강조하고, 건축적 볼륨감이 돋보이는 앵글로 촬영하여 공간의 중심을 잡는 오브제로 활용한다.", "context": "메르크스홀보에는 북해의 자연색을 인테리어 재료로 치환하는 감각적 접근으로 알려진 스튜디오다. 이번 모남 프로젝트는 이들의 공간 설계 철학을 가구라는 단위로 구체화한 결과물이다.", "keywords": ["건축가 가구", "파티나", "물성", "벨기에 디자인", "오브제"], "evidence": "A hand-applied patina builds up unevenly across a surface, so each piece carries a slight variation in tone that a sprayed coating would flatten out.", "kind": "브랜드·캠페인", "depth": 3, "grounding": "full", "depth_reason": "건축가의 설계를 가구로 치환하는 독특한 제작 철학을 담고 있으며, 파티나 기법을 통한 물성 구현 방식이 구체적으로 제시됨.", "sources": [{"n": 1, "type": "공식·1차", "title": "Monâme - Belgian Furniture Collections, Shaped by Architecture", "url": "https://www.moname.be"}, {"n": 2, "type": "RE:COLLECTION 과거 기사", "title": "북해의 모래와 바다를 담은 앤트워프의 해변 펜트하우스 인테리어", "url": "https://www.dezeen.com/2026/09/07/north-sea-coast-seaside-penthouse-merckx-holvoet-architecten/"}], "findings": [{"text": "모남은 건축가의 도면을 가구로 실현하는 스튜디오이자, 건축가의 서명을 보존하는 브랜드로 정의된다.", "s": 1, "quote": "The architect is the author. Atelier Monâme offers architects the opportunity to explore and develop unique objects that integrate seamlessly within their architectural vision."}]}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.dezeen.com/2026/11/21/exterior-staircases-facade/", "title": "계단이 외관이 될 때: 보행을 건축의 입면으로 치환하는 5가지 방식", "original_title": "Five buildings where the staircase is the facade", "url": "https://www.dezeen.com/2026/11/21/exterior-staircases-facade/", "image_url": "https://static-2026.dezeen.com/uploads/2026/11/staircase-buildings-roundup_dezeen-squares_dezeen_2364_col_1-1024x1024.jpg", "video_url": "", "has_video": false, "snippet": "건축의 외관을 단순히 가두는 면이 아닌, 보행자의 이동 경로인 계단으로 구성한 5개의 공공 건축 사례를 조명한다. 인도의 프레스티지 대학교는 460개의 계단식 플랫폼으로 건물의 육중함을 덜어냈고, 알바니아의 티라나 피라미드는 기존 기념비를 계단으로 덮어 시민의 공간으로 전유했다. 계단은 건축의 시각적 형태를 결정하는 동시에 도시와 건물을 물리적으로 연결하는 매개체가 된다.", "genre": "SPACE & ARCH", "source_name": "Dezeen", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "계단이 외관을 이루는 5개의 건물", "deep": {"lens": "계단을 단순한 수직 이동 수단에서 건축의 외피로 확장하여, 건물의 육중함을 덜어내고 보행자의 동선을 입면의 리듬으로 시각화한다.", "why_now": "디지털 피로도가 높은 시대에 건축물이 물리적 보행을 강제하는 입면을 통해 도시와의 접점을 극대화하려는 시도가 늘고 있다.", "mechanism": "인도의 전통적인 계단식 우물 구조를 차용해 중정을 중심으로 빛과 바람을 깊숙이 끌어들이고, 건물의 높이를 보행 가능한 경사로로 변환해 외부 조경과 건물 외벽의 경계를 지운다.", "sensory": "건물 전체를 타고 오르는 계단의 반복적인 선이 만드는 기하학적 리듬과, 옥상까지 이어지는 보행 과정에서 변화하는 도시의 스케일과 조망이 핵심이다.", "transfer": "공간 연출 시 계단을 구조물 뒤에 숨기지 말고, 동선 자체가 건물의 실루엣을 결정하도록 배치하여 카메라가 보행자의 시선을 따라 건물을 관통하게 설계한다.", "context": "엠브이알디브이(MVRDV)는 바르코드 지구와 마이애미 워마 프로젝트에서 보행자의 동선을 중심으로 도시의 밀도를 재구성해왔다. 스뇌헤타(Snøhetta)는 오슬로 오페라 하우스 이후 지속적으로 지붕과 외관을 결합한 보행 공간을 실험하며, 파빌리아 팜처럼 고밀도 환경 속 생태적 거점을 구축하는 데 주력한다.", "keywords": ["계단식 입면", "공공 동선", "지형 순응", "보행 가능한 지붕"], "evidence": "The one thing they all have in common is that they make their stairs the main event.", "kind": "프로젝트", "depth": 5, "grounding": "full", "depth_reason": "계단이라는 단일 요소를 파사드와 사회적 장치로 치환한 구체적인 사례들을 통해 건축적 해법을 명확히 제시한다.", "sources": [{"n": 1, "type": "위키백과", "title": "MVRDV", "url": "https://en.wikipedia.org/wiki/MVRDV"}, {"n": 2, "type": "위키백과", "title": "Snøhetta (company)", "url": "https://en.wikipedia.org/wiki/Sn%C3%B8hetta%20%28company%29"}, {"n": 3, "type": "RE:COLLECTION 과거 기사", "title": "오슬로, 17세기 기록과 현대적 입면이 교차하는 도시 풍경", "url": "https://www.archdaily.com/1184689/oslo-architecture-city-guide-12-buildings-contrasting-historic-and-contemporary-design"}, {"n": 4, "type": "RE:COLLECTION 과거 기사", "title": "마이애미 윈우드의 색채와 광장, 엠브이알디브이가 구축한 인간적 규모", "url": "https://www.dezeen.com/2026/09/01/mvrdv-woma-colourful-residential-miami/"}, {"n": 5, "type": "RE:COLLECTION 과거 기사", "title": "스뇌헤타가 완성한 홍콩의 녹색 폐, 파빌리아 팜 클럽하우스", "url": "https://www.archdaily.com/1185885/pavilia-farm-clubhouses-snohetta"}], "findings": [{"text": "엠브이알디브이는 1993년 위니 마스, 야콥 판 레이스, 나탈리 드 브리스가 설립한 네덜란드 건축 사무소다.", "s": 1, "quote": "MVRDV is a Rotterdam, Netherlands-based architecture and urban design practice founded in 1993 by Winy Maas, Jacob van Rijs and Nathalie de Vries"}, {"text": "스뇌헤타는 노르웨이 오슬로에 본사를 둔 글로벌 건축 사무소다.", "s": 2, "quote": "Snøhetta AS (Norwegian pronunciation: [ˈsnø̀ːˌhɛtːɑ]) is a global architectural firm, founded in Oslo, Norway."}]}, "is_pick": true, "issue_date": "2026-11-22"}, {"id": "https://www.dezeen.com/2026/11/20/atelier-manferdini-virginia-power-station/", "title": "디지털 글리치와 알루미늄 그리드로 번역한 변전소의 전류", "original_title": "Atelier Manferdini uses digital glitches to shape tile-and-metal facade of Virginia power station", "url": "https://www.dezeen.com/2026/11/20/atelier-manferdini-virginia-power-station/", "image_url": "https://static-2026.dezeen.com/uploads/2026/11/manferdini-virginia-power-station-invisible_dezeen_2364_sq-1024x1024.jpg", "video_url": "", "has_video": false, "snippet": "미국 로스앤젤레스의 아틀리에 만페르디니는 버지니아주 크리스털시티의 도미니언 에너지 변전소 외관 프로젝트인 '인비지블'을 진행했다. 이들은 프로세싱 프로그램을 활용한 디지털 글리치와 피트 몬드리안의 작품에서 착안한 10가지 색상의 타일을 하단에 배치했다. 상단에는 간격을 달리한 알루미늄 그리드 패널을 설치해 시시각각 변하는 빛과 그림자의 효과를 구현했다.", "genre": "SPACE & ARCH", "source_name": "Dezeen", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "Atelier Manferdini, 디지털 글리치를 활용해 버지니아 발전소의 타일 및 금속 외관을 설계하다", "deep": {"lens": "기계만을 위한 척박한 기반시설의 외피에 디지털 글리치와 알루미늄의 물성을 입혀 도시의 인간적 스케일로 번역한다.", "why_now": "기계적 효율로만 은폐되던 도심 속 핵심 인프라를 감각적인 도시 공공 장치로 전환하는 설계적 시도가 늘고 있다.", "mechanism": "하단에는 3가지 크기의 타일과 10가지 색상을 프로그래밍의 의도된 오류로 배열하고, 상단에는 거대한 알루미늄 패널을 엇갈리게 적층해 햇빛의 투과율을 조절한다.", "sensory": "하단의 밀도가 높은 색채 패턴과 상단 고요한 금속의 질감이 대비를 이루며, 야간에는 내장된 프로그래밍 LED가 외관을 백라이트 방식으로 밝힌다.", "transfer": "공간 외벽이나 대형 스크린 배경 작업에서 패널의 간격을 조절해 빛을 통과시키는 다중 레이어 구조와 프로그래밍 오류를 시각적 패턴으로 치환하는 기법을 차용한다.", "context": "엘레나 만페르디니가 이끄는 아틀리에 만페르디니는 기능적 건축물에 예술적 서사를 부여하는 작업을 지속해 왔으며, 이번 프로젝트는 도미니언 에너지의 변전소 현대화 과정의 일환으로 수행되었다.", "keywords": ["변전소 외관", "디지털 글리치", "알루미늄 패널", "도시 기반시설", "아틀리에 만페르디니"], "evidence": "Atelier Manferdini has created an expressive facade for a substation in Virginia, USA, using metal to represent the flow of electricity.", "kind": "프로젝트", "depth": 4, "grounding": "full", "depth_reason": "변전소라는 엄격한 기반시설을 디지털 프로그래밍과 금속 타일로 재해석한 독창적인 설계 방식이 구체적으로 드러난다.", "sources": [{"n": 1, "type": "공식·1차", "title": "Welcome to Processing!", "url": "https://processing.org/"}, {"n": 2, "type": "위키백과", "title": "Dominion Energy", "url": "https://en.wikipedia.org/wiki/Dominion%20Energy"}, {"n": 3, "type": "위키백과", "title": "Piet Mondrian", "url": "https://en.wikipedia.org/wiki/Piet%20Mondrian"}], "findings": [{"text": "도미니언 에너지는 버지니아주 등에서 전기를 공급하는 미국의 에너지 기업이다.", "s": 2, "quote": "Dominion Energy, Inc., commonly referred to as Dominion, is an American energy company headquartered in Richmond, Virginia that supplies electricity in parts of Virginia"}]}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.dezeen.com/2026/11/20/can-house-tropicalia/", "title": "하우스 트로피칼리아: 브라질 모더니즘과 산업적 골조의 사적 결합", "original_title": "CAN combines eclectic references for eccentric revamp of London house", "url": "https://www.dezeen.com/2026/11/20/can-house-tropicalia/", "image_url": "https://static-2026.dezeen.com/uploads/2026/11/house-tropicalia-can-architecture-london-residential-houses-extensions-england-uk_dezeen_2364_sq-1024x1024.jpg", "video_url": "", "has_video": false, "snippet": "런던의 건축 스튜디오 캔(CAN)이 설계한 하우스 트로피칼리아는 브라질 모더니즘과 산업 인프라를 결합한 주거 프로젝트다. 건축가는 콘크리트 배수관 타워, 원색의 강철 캐노피, 비정형 석재 등 이질적인 재료를 배치해 거주자의 기억과 취향을 공간에 투영했다. 지면에는 강을 형상화한 자갈 상감 마이크로시멘트 바닥을 깔고, 1층에는 톱날형 지붕을 올려 기능과 서사를 동시에 구현했다.", "genre": "SPACE & ARCH", "source_name": "Dezeen", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "CAN, 런던 주택을 독특하게 개조하기 위해 다양한 스타일을 결합하다", "deep": {"lens": "단일한 미학을 거부하고 이질적인 참조점을 충돌시켜 거주자의 서사를 공간의 물리적 레이어로 치환한다.", "why_now": "균일한 주거 양식에서 벗어나 개인의 기억과 취향을 건축적 장치로 번역하려는 움직임이 가속화되고 있다.", "mechanism": "배수관 타워와 톱날 지붕 같은 산업적 요소를 주거의 구조적 골조로 전유하고, 핑크와 블루를 오가는 수제 타일로 시각적 변주를 주어 공간의 밀도를 높인다.", "sensory": "건조한 콘크리트 질감과 대비되는 광택 있는 수제 타일의 매끄러움, 그리고 톱날 지붕 사이로 쏟아지는 빛의 파편이 공간의 깊이를 만든다.", "transfer": "콘티 설계 시 특정 시대의 예술 운동에서 파생된 강렬한 원색과 산업용 관(tube)을 구조적 포인트로 활용해 공간의 위계와 시선을 분산시킨다.", "context": "캔(CAN)은 이전 작업인 마운틴 뷰(Mountain View) 등에서 보여준 대담한 구조적 실험을 이번 프로젝트에서도 이어간다. 리나 보 바르디(Lina Bo Bardi)의 SESC 폼페이아에서 영감을 받은 수경 시설과 공간 구성은 건축가의 사적 서사를 보편적 주거 문법으로 치환하려는 시도다.", "keywords": ["트로피칼리아", "브라질모더니즘", "산업적골조", "사적서사"], "evidence": "We reject the idea that a project needs to be driven by a single, homogeneous idea or material.", "kind": "프로젝트", "depth": 5, "grounding": "full", "depth_reason": "건축적 참조점을 단순 인용에 그치지 않고 구체적인 재료와 구조적 장치로 번역해낸 설계 방식이 돋보인다.", "sources": [{"n": 1, "type": "공식·1차", "title": "CAN | Architecture & Ideas Studio", "url": "https://can-site.co.uk/"}, {"n": 3, "type": "위키백과", "title": "Lina Bo Bardi", "url": "https://en.wikipedia.org/wiki/Lina%20Bo%20Bardi"}, {"n": 4, "type": "RE:COLLECTION 과거 기사", "title": "시야를 압도하는 규모와 구조: 주변 시야를 교란하는 전시장치들", "url": "https://www.designboom.com/art/peripheral-vision-artwork-exceeds-eye/"}], "findings": [{"text": "리나 보 바르디는 브라질 베르나큘러 디자인이 현대 브라질 건축에 미치는 영향에 주목했다.", "s": 3, "quote": "she quickly became intrigued with Brazilian vernacular design and how it could influence a modern Brazilian architecture."}, {"text": "리나 보 바르디의 투명 유리 이젤 전시는 정면 응시라는 전통적 관람 방식을 해체한다.", "s": 4, "quote": "리나 보 바르디의 투명 유리 이젤은 정면 응시라는 전통적인 관람 방식을 무너뜨린다."}]}, "is_pick": true, "issue_date": "2026-11-22"}, {"id": "https://www.archdaily.com/1188661/mapping-memory-reconstructing-architecture-beyond-physical-evidence", "title": "기억의 매핑: 물리적 증거를 넘어 공간의 진실을 재구성하는 법", "original_title": "Mapping Memory: Reconstructing Architecture Beyond Physical Evidence", "url": "https://www.archdaily.com/1188661/mapping-memory-reconstructing-architecture-beyond-physical-evidence", "image_url": "https://images.adsttc.com/media/images/6af9/1511/c23f/1f01/895a/feb8/large_jpg/mapping-memory-reconstructing-architecture-beyond-physical-evidence_3.jpg?1794708762", "video_url": "", "has_video": false, "snippet": "시각적 접근이 차단된 시리아 세드나야 교도소와 분단된 키프로스 파마구스타 등, 물리적 데이터가 부족한 공간을 재구성하는 시도가 이어지고 있다. 포렌식 아키텍처(Forensic Architecture)와 연구자들은 생존자의 청각적 기억과 증언을 바탕으로 공간의 치수와 구조를 도출한다. 이는 파괴되거나 접근 불가능한 장소를 건축적 증거로 복원하는 새로운 조사 기법이다.", "genre": "SPACE & ARCH", "source_name": "ArchDaily", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "기억의 매핑: 물리적 증거를 넘어 건축을 재구성하기", "deep": {"lens": "건축은 도면이 아닌 누적된 기억의 총합이며, 소리와 메아리는 공간의 물리적 골조를 증명하는 가장 정밀한 측량 도구가 된다.", "why_now": "디지털 모델링 기술이 정교해짐에 따라, 이제 공간 재구성은 단순한 재현을 넘어 은폐된 권력의 흔적을 추적하고 전쟁 범죄를 증명하는 법의학적 수단으로 진화했다.", "mechanism": "생존자의 증언을 바탕으로 한 3D 모델링에 음향 분석을 결합한다. 특히 환기구와 파이프를 통해 전달되는 소리의 잔향과 메아리 시간을 역산하여 벽체 사이의 거리와 공간의 부피를 추정한다.", "sensory": "어둠 속에서 예민해진 청각은 19데시벨(dB)의 미세한 속삭임 변화까지 포착한다. 금속 파이프를 타고 흐르는 소음과 좁은 복도의 불규칙한 메아리가 공간의 폐쇄적 스케일을 물리적으로 체감하게 한다.", "transfer": "공간 연출 시 시각적 단서 대신 특정 소리의 반사율과 울림 시간을 활용해 관객이 공간의 깊이감을 인지하도록 설계하라. 16mm 필름의 입자처럼 불완전한 기억을 파편화된 조명으로 연출하면 공간의 서사가 극대화된다.", "context": "포렌식 아키텍처는 에얄 와이즈만(Eyal Weizman)이 이끄는 런던 골드스미스 대학 기반의 연구 그룹으로, 건축 기술을 활용해 국가 폭력을 조사한다. 로렌스 아부 함단(Lawrence Abu Hamdan)은 이들과 협업해 소리의 정치적 효과를 탐구하며, 2019년 터너상을 수상한 바 있다. 이는 과거 RE:COLLECTION에서 다룬 베이루트 공습 사건의 디지털 재구성 사례와 맥락을 같이 한다.", "keywords": ["포렌식 아키텍처", "공간 재구성", "청각적 증거", "카운터 매핑"], "evidence": "Sound provided another way to reconstruct the interior.", "kind": "프로젝트", "depth": 5, "grounding": "full", "depth_reason": "건축적 재구성이 단순한 기술적 복원을 넘어 범죄 증거로 기능하는 구체적 기법과 방법론을 제시하고 있어 실무 적용 가치가 매우 높다.", "sources": [{"n": 1, "type": "공식·1차", "title": "Saydnaya — Lawrence Abu Hamdan", "url": "https://labuhamdan.squarespace.com/saydnaya?utm_medium=website&utm_source=archdaily.com"}, {"n": 3, "type": "위키백과", "title": "Forensic Architecture", "url": "https://en.wikipedia.org/wiki/Forensic%20Architecture"}, {"n": 4, "type": "위키백과", "title": "Lawrence Abu Hamdan", "url": "https://en.wikipedia.org/wiki/Lawrence%20Abu%20Hamdan"}], "findings": [{"text": "로렌스 아부 함단은 세드나야 교도소 내 수감자들의 속삭임이 2011년 이후 19데시벨 감소했음을 증명하며 이를 죽음의 수용소로 변모한 증거로 제시했다.", "s": 1, "quote": "In the absence of any other material evidence, the nineteen-decibel drop in the capacity to speak stands as testament to the transformation of Saydnaya from a prison to a death camp."}, {"text": "포렌식 아키텍처는 건축가, 예술가, 소프트웨어 개발자, 조사 전문 기자 등 다학제적 팀으로 구성되어 국가 폭력 사례를 조사한다.", "s": 3, "quote": "It consists of an interdisciplinary team of investigators including architects, scholars, artists, filmmakers, software developers, investigative journalists, archaeologists, lawyers, and scientists."}, {"text": "로렌스 아부 함단은 2023년 소리 및 음향 분석을 전문으로 하는 인권 조사 기관 '이어샷(Earshot)'을 설립했다.", "s": 4, "quote": "In 2023 he founded Earshot, the first agency for sound and acoustic analysis dedicated to open-source investigators and the field of human rights."}]}, "is_pick": true, "issue_date": "2026-11-22"}, {"id": "https://www.archdaily.com/1188648/fleischerei-a-restaurant-reworked-allen-kaufmann-architekten", "title": "시간의 겹을 남긴 베를린의 정육점 레스토랑 개보수", "original_title": "FLEISCHEREI, A RESTAURANT REWORKED / Allen Kaufmann Architekten", "url": "https://www.archdaily.com/1188648/fleischerei-a-restaurant-reworked-allen-kaufmann-architekten", "image_url": "https://images.adsttc.com/media/images/6af7/debe/eabd/2a00/0192/f26a/large_jpg/AK_110_1_FEATURED.jpg?1794629325", "video_url": "", "has_video": false, "snippet": "알렌 카우프만 아키텍텐이 독일 베를린에서 210제곱미터 규모의 플라이셰라이 레스토랑을 개보수했다. 이 공간은 1911년 건물의 뼈대와 과거 정육점, 2009년 문을 연 레스토랑의 흔적을 고스란히 품고 있다.", "genre": "SPACE & ARCH", "source_name": "ArchDaily", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "FLEISCHEREI, 새롭게 단장한 레스토랑 / Allen Kaufmann Architekten", "deep": {"lens": "백년의 시간 동안 쌓인 겹을 지우지 않고 재료의 층위로 드러낸다.", "why_now": "과거의 공간 유산을 매끄럽게 덮어버리는 대신 시간에 따른 흔적을 그대로 노출하는 태도가 주목받는다.", "mechanism": "1911년의 건축 골조와 이전 식당의 기억을 간직한 요소들을 남겨 다층적인 시간의 레이어를 형성한다.", "sensory": "오래된 벽체와 새로운 마감재가 부딪히며 거칠고 단단한 물성의 대비를 이룬다.", "transfer": "철거 대신 과거의 흔적을 남긴 벽면을 배경으로 삼고, 차가운 금속 조명을 배치해 시간의 간극을 시각화한다.", "context": "알렌 카우프만 아키텍텐은 베를린을 기반으로 공간과 가구를 아우르며 독창적인 물성 실험을 이어가고 있다.", "keywords": ["공간개보수", "역사적흔적", "베를린건축", "재료의레이어"], "evidence": "Fleischerei carries the traces of a 1911 building, a former butcher shop and the restaurant that opened there in 2009", "kind": "프로젝트", "depth": 2, "grounding": "thin", "depth_reason": "원문 설명이 짧고 구체적인 개보수 기법이나 도면 정보가 부족해 평이한 수준에 머문다.", "sources": [], "findings": []}, "is_pick": true, "issue_date": "2026-11-22"}, {"id": "https://www.archdaily.com/1189013/alejandro-munoz-miranda-architecture", "title": "알레한드로 무뇨스 미란다의 건축 궤적: 기하학, 빛, 그리고 텍토닉스", "original_title": "Alejandro Muñoz Miranda. Architecture", "url": "https://www.archdaily.com/1189013/alejandro-munoz-miranda-architecture", "image_url": "https://images.adsttc.com/media/images/6b00/451e/eabd/2a00/0193/29f9/large_jpg/P14_Munoz_Miranda_Portada_web.jpg?1795179812", "video_url": "", "has_video": false, "snippet": "스페인 그라나다 건축대학의 알레한드로 무뇨스 미란다가 2004년부터 2026년까지 완공한 12개의 주요 작품을 담은 첫 번째 단행본이다. 기관 본부, 어린이 센터, 공공 거리 정비부터 장례식장, 주거용 건물, 알람브라 궁전 인근 소형 호텔에 이르는 다양한 프로그램 속에서 기하학, 빛, 텍토닉스라는 일관된 철학을 전개한다.", "genre": "SPACE & ARCH", "source_name": "ArchDaily", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "알레한드로 무뇨스 미란다. 건축", "deep": {"lens": "케네스 프램튼의 사유를 이어받아 그라나다의 지형과 구조 속에 기하학과 빛을 단단하게 구축한다.", "why_now": "다양한 프로그램 속에서 지형과 구조의 본질을 관통하는 건축적 태도를 한 권의 책으로 종합해 볼 수 있는 시점이다.", "mechanism": "케네스 프램튼 지도 아래 박사학위 논문을 쓰며 다듬은 기하학적 엄밀함과 구조적 물성을 바탕으로, 서로 다른 기능의 공간을 텍토닉스 언어로 일관되게 엮어낸다.", "sensory": "그라나다의 거친 지형과 대비되는 명확한 기하학적 선, 그리고 건물 내부로 깊숙이 파고드는 강렬한 빛의 낙차가 공간의 물성을 강조한다.", "transfer": "다양한 프로그램의 공간 시퀀스를 설계할 때, 지형의 조건에 기하학적 축을 먼저 대입하고 빛이 드리우는 낙차를 계산해 텍토닉스 중심의 숏을 구성한다.", "context": "저자인 알레한드로 무뇨스 미란다는 그라나다 건축대학의 건축 설계 교수로 재직 중이며, 현대 건축 비평가인 케네스 프램튼의 지도 아래 박사학위 논문을 수행했다.", "keywords": ["알레한드로무뇨스미란다", "텍토닉스", "비판적지역주의", "그라나다건축", "모노그래프"], "evidence": "The first monograph devoted to the built work of Alejandro Muñoz Miranda (Granada, 1974), architect and professor of Architectural Design at the School of Architecture of Granada.", "kind": "프로젝트", "depth": 3, "grounding": "full", "depth_reason": "건축가와 작품 세계를 다룬 첫 단행본과 완공작 목록을 상세히 전하나, 세부적인 도면이나 구체적 시공 디테일이 원문에 부족하다.", "sources": [], "findings": []}, "is_pick": true, "issue_date": "2026-11-22"}, {"id": "https://www.archdaily.com/1189004/designing-innovation-ecosystems-lessons-from-three-transformative-campuses", "title": "혁신을 담는 그릇, 세 가지 캠퍼스가 증명하는 지역 기반의 통합 설계", "original_title": "Designing innovation ecosystems: Lessons from three transformative campuses", "url": "https://www.archdaily.com/1189004/designing-innovation-ecosystems-lessons-from-three-transformative-campuses", "image_url": "https://images.adsttc.com/media/images/6b00/40e9/eabd/2a00/0193/29b5/large_jpg/2026_Q4_webinar_social_image.jpg?1795178747", "video_url": "", "has_video": false, "snippet": "스탠텍(Stantec)이 주관하는 웨비나를 통해 혁신 생태계를 구축한 세 곳의 캠퍼스 사례를 조명한다. 각 프로젝트는 지역의 고유한 문화와 경제적 기회를 분석하여, 협업과 발견을 촉진하는 적응형 환경으로 구현되었다. 전략적 우선순위와 공동체의 열망을 통합 설계 프로세스로 조율한 과정이 핵심이다.", "genre": "SPACE & ARCH", "source_name": "ArchDaily", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "혁신 생태계 설계: 세 곳의 혁신적인 캠퍼스에서 얻은 교훈", "deep": {"lens": "완공된 건축물이 아닌, 지역의 경제와 문화를 수용하고 변화에 대응하는 유연한 공간의 조직 방식을 관찰한다.", "why_now": "기술 중심의 혁신이 물리적 공간과 결합할 때 발생하는 지역적 마찰과 기회를 설계로 풀어내는 통합적 접근이 필요한 시점이다.", "mechanism": "전략적 목표와 경제적 기회를 공간의 적응형 환경으로 치환하여, 사용자의 협업을 유도하는 동선을 구축한다.", "sensory": "고정된 기능이 아닌 시간의 흐름에 따라 변주되는 공간의 유연함과, 다양한 집단이 섞이는 과정에서 발생하는 밀도를 체감한다.", "transfer": "공간 연출 시 특정 목적을 위한 고정적 레이아웃 대신, 사용자의 활동 변화에 따라 가변적으로 재구성 가능한 모듈형 가구와 동선을 콘티에 반영한다.", "context": "스탠텍은 1954년 캐나다에서 설립된 다국적 전문 서비스 기업으로, 인프라와 시설 프로젝트 전반을 다룬다. 본 자료는 아키데일리(ArchDaily)에 게시된 웨비나 정보를 바탕으로 작성되었다.", "keywords": ["혁신 생태계", "캠퍼스 설계", "통합 디자인", "적응형 환경", "지역 기반"], "evidence": "each project aligned strategic priorities, economic opportunities, and community aspirations with adaptable environments designed to foster collaboration, discovery, and long-term growth.", "kind": "뉴스·이슈", "depth": 2, "grounding": "thin", "depth_reason": "원문의 정보가 웨비나 홍보성 요약에 그쳐 구체적인 설계 기법이나 사례의 상세 내용이 부족하다.", "sources": [{"n": 1, "type": "위키백과", "title": "Stantec", "url": "https://en.wikipedia.org/wiki/Stantec"}, {"n": 2, "type": "위키백과", "title": "ArchDaily", "url": "https://en.wikipedia.org/wiki/ArchDaily"}], "findings": [{"text": "스탠텍은 1954년 캐나다 에드먼턴에서 설립된 이후 전 세계 6개 대륙에서 인프라 및 시설 프로젝트를 수행하는 전문 서비스 기업이다.", "s": 1, "quote": "The company was founded in 1954, as D. R. Stanley Associates in Edmonton, Alberta, Canada. Stantec provides professional consulting services in planning, engineering, architecture, interior design, landscape architecture"}]}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.archdaily.com/1189008/aedas-invites-architecture-graduates-across-saudi-arabia-to-enter-its-2027-architecture-graduate-awards", "title": "에이다스, 사우디아라비아 건축학도 대상 2027 졸업 작품 어워드 개최", "original_title": "Aedas Invites Architecture Graduates Across Saudi Arabia to Enter its 2027 Architecture Graduate Awards", "url": "https://www.archdaily.com/1189008/aedas-invites-architecture-graduates-across-saudi-arabia-to-enter-its-2027-architecture-graduate-awards", "image_url": "https://images.adsttc.com/media/images/6b00/4238/eabd/2a00/0193/29d7/large_jpg/Aedas_Poster__1_.jpg?1795179075", "video_url": "", "has_video": false, "snippet": "글로벌 건축 사무소 에이다스(Aedas)가 사우디아라비아의 건축학과 졸업생을 대상으로 2027 건축 졸업생 어워드 참가자를 모집한다. 기존에 완료한 졸업 프로젝트를 제출하는 방식이며, 최종 후보작은 전시 기회를 얻고 수상자에게는 별도의 인정이 주어진다. 이는 아랍에미리트와 이집트 등에서 이어온 지역 인재 양성 프로그램을 사우디아라비아로 확장한 사례다.", "genre": "SPACE & ARCH", "source_name": "ArchDaily", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "Aedas, 사우디아라비아 전역의 건축학과 졸업생을 2027년 건축학과 졸업생 어워드에 초청", "deep": {"lens": "단순한 공모전을 넘어 글로벌 실무 조직이 지역 대학의 산출물을 자사 인재 풀로 흡수하고 현지 건축 담론을 주도하려는 전략적 포석이다.", "why_now": "사우디아라비아의 대규모 인프라 개발이 가속화됨에 따라 현지 건축 인재 확보와 교육적 연대가 실무적 필수 과제로 부상했다.", "mechanism": "별도의 추가 과제 없이 기존 학위 프로젝트를 그대로 제출하게 하여 학생의 부담을 낮추고, 실무 현장의 기준에서 검증된 아이디어를 선별하는 구조다.", "sensory": "졸업생들의 비정형적이고 실험적인 설계안이 실무자의 시선으로 필터링되어 전시되는 과정에서 학구적 열기와 실무적 엄격함이 교차한다.", "transfer": "졸업 작품의 레이아웃을 현장 실무자가 검토하는 방식처럼, 정제되지 않은 초기 아이디어를 프로토타입 단계에서 발굴하는 스카우팅 프로세스로 활용 가능하다.", "context": "에이다스는 2002년 키스 그리피스(Keith Griffiths)가 설립한 글로벌 건축 사무소로, 홍콩과 리야드를 포함한 12개 도시에서 마스터플랜과 도시 설계를 수행한다. 과거 심천 황강항 프로젝트에서 보인 수평적 금속 핀과 층계형 매스 설계처럼, 이들은 대규모 인프라를 다루는 실무적 감각을 교육 프로그램에도 투영하고자 한다.", "keywords": ["에이다스", "건축공모", "사우디아라비아", "인재양성"], "evidence": "Final-year architecture students and recent graduates across the Kingdom can enter the graduation project they have already completed", "kind": "행사·공모", "depth": 2, "grounding": "partial", "depth_reason": "공모전 개최 소식이라는 단순 정보 전달에 그치며, 구체적인 심사 기준이나 이전 프로그램의 성과에 대한 상세 데이터가 부족하다.", "sources": [{"n": 1, "type": "위키백과", "title": "Aedas", "url": "https://en.wikipedia.org/wiki/Aedas"}, {"n": 2, "type": "RE:COLLECTION 과거 기사", "title": "심천-홍콩 국경의 관문, 에이다스의 층계형 이민 허브", "url": "https://www.dezeen.com/2026/11/01/new-huanggang-port-development-aedas-shenzhen-hong-kong/"}], "findings": [{"text": "에이다스는 2002년 웨일스 건축가 키스 그리피스가 설립하였으며 현재 12개 도시에 지사를 두고 있다.", "s": 1, "quote": "Aedas is an architectural firm founded by the Welsh architect Keith Griffiths. Aedas employs 1,000 staff in its twelve offices in Hong Kong, Beijing, Shanghai, Shenzhen, Singapore, Dubai, Riyadh, Delhi and Seattle"}]}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.architecturaldigest.com/story/50-ad-approved-photographers", "title": "공간의 서사를 결정짓는 시각적 언어: 건축 사진가 선정 가이드", "original_title": "AD-Approved Interior Photographers to Book for Your Next Project", "url": "https://www.architecturaldigest.com/story/50-ad-approved-photographers", "image_url": "https://media.architecturaldigest.com/photos/6afc981962312feba5cc576d/master/pass/___AD0626_FRIEDMAN_21%20copy.jpg", "video_url": "", "has_video": false, "snippet": "건축 전문 매체 아키텍처럴 다이제스트가 내부 사진 편집자들이 엄선한 180여 명의 인테리어 사진가 리스트를 공개했다. 이들은 지형과 기후에 따른 빛의 변화를 포착하고 공간의 고유한 성격을 서사로 번역하는 역할을 수행한다. 프로젝트의 성패를 좌우하는 사진은 디자이너의 포트폴리오를 구성하는 핵심 자산이다.", "genre": "SPACE & ARCH", "source_name": "Architectural Digest", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "다음 프로젝트에 예약할 수 있는 AD 승인 인테리어 사진작가", "deep": {"lens": "단순 기록을 넘어 공간의 분위기와 물리적 질감을 서사로 치환하는 사진가의 시각적 결단이 프로젝트의 생명력을 결정한다.", "why_now": "디지털 피로도가 높은 시대, 공간의 물성과 빛의 입자를 정확하게 포착한 이미지는 디자이너의 독창성을 증명하는 가장 강력한 비즈니스 도구다.", "mechanism": "사진가는 자연광의 각도와 실내 인공 조명의 대비를 조절하여 공간의 깊이감을 확보하고, 광각과 클로즈업을 교차하여 구조적 위엄과 일상의 친밀함을 동시에 연출한다.", "sensory": "창을 통해 쏟아지는 강렬한 직사광선부터 어두운 복도의 부드러운 음영까지, 공간이 머금은 시간의 무게와 재료의 질감이 화면 위에서 촉각적으로 재구성된다.", "transfer": "콘티 작성 시 공간의 '시간대'를 설정하고, 특정 시간의 빛이 벽면의 마감재와 어떻게 반응하는지를 묘사하여 촬영의 방향성을 구체화하라.", "context": "아키텍처럴 다이제스트는 1920년 창간 이후 스타일 중심의 인테리어와 조경을 다루며 글로벌 디자인 권위지로 자리 잡았다. 이 매체는 세레나 윌리엄스의 사적 공간이나 해리슨 포드의 목공 작업실 등 공간에 투영된 거주자의 서사를 포착하는 방식으로 건축적 기록의 가치를 확장해 왔다.", "keywords": ["건축사진", "공간서사", "포트폴리오", "빛의연출", "아키텍처럴다이제스트"], "evidence": "The right interior photographers can make or break the way your space is remembered.", "kind": "뉴스·이슈", "depth": 3, "grounding": "full", "depth_reason": "전문 사진가 활용의 전략적 중요성을 강조하나, 구체적인 촬영 기법보다는 인력 리스트 중심의 정보 전달에 집중하고 있다.", "sources": [{"n": 1, "type": "위키백과", "title": "Architectural Digest", "url": "https://en.wikipedia.org/wiki/Architectural%20Digest"}, {"n": 2, "type": "RE:COLLECTION 과거 기사", "title": "코트를 떠난 챔피언의 공간, 세레나 윌리엄스의 주거 포트폴리오", "url": "https://www.architecturaldigest.com/story/where-does-serena-williams-live"}, {"n": 3, "type": "RE:COLLECTION 과거 기사", "title": "지속 가능한 주거 리노베이션을 위한 세 가지 건축적 전략", "url": "https://www.architecturaldigest.com/story/the-ideas-defining-home-renovations-today-according-to-top-architects"}, {"n": 4, "type": "RE:COLLECTION 과거 기사", "title": "목수였던 배우 해리슨 포드, 그가 직접 지은 집과 가구의 기록", "url": "https://www.architecturaldigest.com/story/harrison-ford-at-home-photos-of-the-hollywood-heartthrobs-life-off-set"}], "findings": [{"text": "아키텍처럴 다이제스트는 1920년에 창간된 월간지로 인테리어와 조경을 주요 주제로 다룬다.", "s": 1, "quote": "Architectural Digest (stylized in all caps) is an American monthly magazine founded in 1920. Its principal subjects are interior design and landscaping"}]}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.architecturaldigest.com/story/interior-photographers-in-the-southwest", "title": "텍사스의 강렬한 태양과 유타의 눈부신 설광을 담는 남서부 인테리어 사진가 9인", "original_title": "9 Interior Photographers in the Southwest to Book for Your Next Design Project", "url": "https://www.architecturaldigest.com/story/interior-photographers-in-the-southwest", "image_url": "https://media.architecturaldigest.com/photos/6afdfedb7b2adeda65ee6477/master/pass/___02-YondMartin2025%20-%20Inquiries%20Mabey.jpg", "video_url": "", "has_video": false, "snippet": "미국 남서부 지역의 극단적인 자연광과 기후 속에서 인테리어와 건축의 물성을 포착하는 사진가 9인의 포트폴리오를 조명한다. 텍사스의 강렬한 햇빛부터 오클라호마와 유타의 주거 공간까지, 주변 풍경의 극적인 대조를 담아내는 작업 방식을 살펴본다.", "genre": "SPACE & ARCH", "source_name": "Architectural Digest", "collected_at": "2026-11-22 00:19", "healed": true, "title_mt": "다음 인테리어 디자인 프로젝트에 고용할 만한 미국 남서부 지역의 인테리어 사진작가 9명", "deep": {"lens": "사막의 강한 태양광과 설산의 눈부신 반사광을 이용해 건축물의 물성을 극적으로 드러낸다.", "why_now": "디지털 매체에서 공간의 물성과 질감을 전달하는 시각적 기록의 중요성이 커지는 가운데, 지역적 기후 조건에 대응하는 사진가의 시선이 주목받는다.", "mechanism": "강한 자연광을 역이용하여 실내의 미세한 질감과 재료의 물성을 강조하고, 저널리즘적 접근으로 공간의 현실감을 포착한다.", "sensory": "눈이 멀 듯한 텍사스의 직사광선과 유타 설원의 백색 반사광이 창문을 통해 실내 깊숙이 파고드는 시각적 대비를 전달한다.", "transfer": "공간 촬영 시 지역 고유의 빛 각도와 기후적 특성을 반영해 인공 조명 대신 자연광의 강약을 콘티의 주요 축으로 설정한다.", "context": "미국 월간지 아키텍처럴 다이제스트(Architectural Digest)는 1920년에 창간되어 인테리어 디자인과 조경을 주요 주제로 다루며 전 세계적인 영향력을 유지해 왔다.", "keywords": ["인테리어 사진", "남서부 기후", "자연광", "공간 기록"], "evidence": "From the blinding sunshine in Texas to the glare off the snow in Utah, interior photographers in the Southwest have a distinct set of challenges", "kind": "리스트·라운드업", "depth": 3, "grounding": "full", "depth_reason": "남서부 지역의 사진가 9인을 소개하는 라운드업 기사로 정보 전달 중심이다.", "sources": [{"n": 1, "type": "위키백과", "title": "Architectural Digest", "url": "https://en.wikipedia.org/wiki/Architectural%20Digest"}], "findings": [{"text": "아키텍처럴 다이제스트는 1920년에 창간된 미국의 월간지이다.", "s": 1, "quote": "Architectural Digest (stylized in all caps) is an American monthly magazine founded in 1920."}]}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.designboom.com/architecture/976-triangular-modules-compose-star-patterned-timber-canopy-in-switzerland/", "title": "스위스 스텔라 파빌리온: 976개 목재 모듈로 빚은 별 모양의 지붕", "original_title": "976 triangular modules compose star-patterned timber canopy in switzerland", "url": "https://www.designboom.com/architecture/976-triangular-modules-compose-star-patterned-timber-canopy-in-switzerland/", "image_url": "https://www.designboom.com/wp-content/dbsub/471061/2026-11-20/stellar-pavilion-a-roof-for-village-life-1-6b001941b3fd5.jpg", "video_url": "", "has_video": false, "snippet": "에디타 아우구스티노비츠와 서멈 엔지니어링이 스위스 슈타인 광장에 설계한 스텔라 파빌리온은 4개의 가지형 기둥이 19.8m 규모의 지붕을 지탱하는 목재 구조물이다. 약 3,000개의 직선 목재 부재를 976개의 삼각형 모듈로 구성해 파라메트릭하게 접힌 형태를 완성했다. 상단에는 반투명 막을 덮어 빛을 필터링하며, 중앙 기둥 사이 11.3m의 개방된 공간을 확보해 공공 활동을 수용한다.", "genre": "SPACE & ARCH", "source_name": "Designboom Architecture", "collected_at": "2026-11-22 00:20", "healed": true, "title_mt": "976개의 삼각형 모듈로 구성된 스위스의 별 모양 목재 캐노피", "deep": {"lens": "직선 목재 부재를 삼각형 모듈로 분절해 곡면을 구현하고, 구조적 압축력을 기둥으로 자연스럽게 흘려보내는 기하학적 효율성이 돋보인다.", "why_now": "디지털 설계와 CNC 가공을 통해 복잡한 비정형 구조를 표준화된 모듈로 치환하여 시공 효율을 극대화하는 방식은 현대 건축의 중요한 과제다.", "mechanism": "지붕의 접힌 면은 주 응력선을 따라 기둥으로 이어지며, 976개의 삼각형 모듈은 반복적인 패턴을 통해 하중을 분산하고 빗물을 중앙 기둥으로 유도한다.", "sensory": "반투명 막을 통과한 자연광이 목재 격자 구조를 투영하며, 별 모양의 패턴이 공간 아래에 은은한 그림자 층을 형성한다.", "transfer": "공간 연출 시 목재 부재를 직선으로 절단해 곡면을 만드는 모듈화 기법을 차용하라. 대형 천장 구조물 제작 시, 반복되는 기하학적 유닛을 프리패브 방식으로 조립해 현장 시공 오차를 줄이는 콘티를 구성할 수 있다.", "context": "이 프로젝트는 바젤의 1912년 하일리그가이스트 교회 네오고딕 별 모양 볼트와 콜비욘 새더의 1961년 압축 하중 구조 막 연구를 현대적으로 재해석했다.", "keywords": ["목재 파빌리온", "파라메트릭", "모듈러 건축", "구조적 기하학"], "evidence": "976 triangular modules compose star-patterned timber canopy", "kind": "프로젝트", "depth": 4, "grounding": "full", "depth_reason": "파라메트릭 설계와 모듈화 조립의 구체적 공정이 명확하며, 역사적 레퍼런스를 현대 기술로 치환한 논리가 선명하다.", "sources": [], "findings": []}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.wallpaper.com/design-interiors/design-miami-2026-things-to-see", "title": "마이애미 아트 위크 2026: 도시를 무대로 한 감각적 실천", "original_title": "10 things to see during Design Miami, from Play-Doh to Playboy", "url": "https://www.wallpaper.com/design-interiors/design-miami-2026-things-to-see", "image_url": "https://cdn.mos.cms.futurecdn.net/44p9x3XgrDA9pZ9m6oE3hh-1920-80.jpg", "video_url": "", "has_video": false, "snippet": "12월 첫 주, 마이애미 아트 위크가 열린다. 디자인 마이애미와 아트 바젤을 중심으로 전역에서 수백 개의 전시와 설치 작업이 펼쳐지며, 디자인 호텔과 리프라인 등 도시 곳곳이 예술적 실험의 장으로 변모한다. 올해는 오브젝트 오브 커먼 이벤츠의 키네틱 설치물부터 플레이도 협업까지, 산업과 공공 영역을 넘나드는 다채로운 기획이 눈에 띈다.", "genre": "SPACE & ARCH", "source_name": "Wallpaper*", "collected_at": "2026-11-22 00:20", "healed": true, "title_mt": "플레이도부터 플레이보이까지, 디자인 마이애미에서 놓치지 말아야 할 10가지", "deep": {"lens": "전시장을 넘어 도시의 물리적 지형과 일상적 사물을 창작의 재료로 삼아, 관람객을 수동적 감상자가 아닌 공간의 주체로 호명한다.", "why_now": "디지털 피로도가 극에 달한 시점에, 물리적 공간의 역사성과 촉각적 재료를 전면에 내세운 기획들이 동시대 창작자들에게 새로운 돌파구를 제시한다.", "mechanism": "오브젝트 오브 커먼 이벤츠는 기하학적 조형물에 회전, 반사, 증기 방출 기능을 탑재해 관람객과 능동적으로 반응하는 사회적 시노그래피를 구축한다.", "sensory": "레진의 불투명한 질감, 3D 프린팅과 수공예가 결합된 세라믹의 거친 표면, 그리고 해안가에서 50명의 무용수가 만들어내는 집단적 움직임이 공간의 밀도를 높인다.", "transfer": "광고 콘티 구성 시, 고정된 오브제에 기계적 장치(회전, 증기)를 결합하여 공간의 시간성을 부여하거나, 텍스처가 살아있는 전통 소재를 현대적 디지털 조형으로 치환하는 방식을 차용하라.", "context": "오브젝트 오브 커먼 이벤츠는 그리스 피레우스의 레진 공장을 거점으로 물성의 우연성을 창작의 동력으로 삼는 작업을 지속해왔다. 디자인 마이애미는 2005년 설립 이후 서울 등 위성 도시로 영향력을 확장하며 전통 공예의 현대적 해석을 이끌어내고 있다. 캐리 메이 윔스는 월페이퍼 30주년 기념 작업에 참여하는 등 동시대 시각 예술의 경계를 넓히는 인물이다.", "keywords": ["마이애미아트위크", "디자인마이애미", "오브젝트오브커먼이벤츠", "공공설치", "물성실험"], "evidence": "The totems, installed at various places throughout the tony shopping quarter, will rotate, reflect, emit sounds and even spout vapour.", "kind": "프로젝트", "depth": 5, "grounding": "full", "depth_reason": "전시, 공공 설치, 브랜드 협업 등 구체적인 사례를 통해 공간 설계와 연출에 직결되는 기술적 장치와 물성 해석을 명확히 제시함.", "sources": [{"n": 2, "type": "공식·1차", "title": "REEFLINE", "url": "https://www.thereefline.org/"}, {"n": 5, "type": "RE:COLLECTION 과거 기사", "title": "우연과 레진의 물성으로 실험하는 오브젝트 오브 커먼 이벤트의 피레우스 워크숍", "url": "https://www.wallpaper.com/design-interiors/work-in-process-objects-of-common-interest-greece"}, {"n": 6, "type": "RE:COLLECTION 과거 기사", "title": "디자인 마이애미 서울, 전통 공예를 재해석한 소장품 7선", "url": "https://www.dezeen.com/2026/09/08/design-miami-seoul-in-situ/"}, {"n": 7, "type": "RE:COLLECTION 과거 기사", "title": "월페이퍼 30주년, 17인의 크리에이터가 빚어낸 케이크의 형상들", "url": "https://www.wallpaper.com/art/wallpaper-30-birthday-cakes"}], "findings": [{"text": "오브젝트 오브 커먼 이벤츠는 그리스 피레우스에 800제곱미터 규모의 레진 공장을 열고 수제 레진 공예 기법을 실험한다.", "s": 5, "quote": "오브젝트 오브 커먼 이벤츠(Objects of Common Interest)의 엘레니 페탈로티와 레오니다스 트람푸키스는 그리스 피레우스에 800제곱미터 규모의 레진 공장을 열었다."}, {"text": "디자인 마이애미 서울은 디자인랩 W에서 한국 전통 공예를 현대적 디자인 언어로 전환하는 전시를 선보였다.", "s": 6, "quote": "이번 전시는 디자인랩 W에서 개최되어 전통적 물성을 현대적 디자인 언어로 전환하는 작업들을 선보였다."}, {"text": "리프라인은 마이애미 해안에서 800피트 떨어진 곳에 위치한 하이브리드 리프이자 공공 조각 공원이다.", "s": 2, "quote": "A pioneering underwater public sculpture park and hybrid reef, a new model of cultural and ecological infrastructure 800ft off the coast of Miami Beach"}]}, "is_pick": true, "issue_date": "2026-11-22"}, {"id": "https://www.wallpaper.com/architecture/residential/charred-timber-house-nustudio-los-angeles-hills-usa", "title": "로스앤젤레스 언덕 위, 탄화 목재로 감싼 1950년대 랜치 하우스의 변주", "original_title": "Step inside this charred timber house, a warm family retreat in the Los Angeles Hills", "url": "https://www.wallpaper.com/architecture/residential/charred-timber-house-nustudio-los-angeles-hills-usa", "image_url": "https://cdn.mos.cms.futurecdn.net/hSEGHhUmhi5yZ4rzzVSjcB-1920-80.jpg", "video_url": "", "has_video": false, "snippet": "안무가이자 감독인 안토니 지난자르와 애슐리 에반스가 1950년대 랜치 하우스를 현대적인 주거 공간으로 재해석했다. 누스튜디오의 네이선 어반은 기존 건축의 뼈대를 유지하며 탄화 목재 파사드를 입히고, 벨기에와 일본의 미니멀리즘을 조화시켜 실내외가 유기적으로 흐르는 안식처를 설계했다.", "genre": "SPACE & ARCH", "source_name": "Wallpaper*", "collected_at": "2026-11-22 00:20", "healed": true, "title_mt": "로스앤젤레스 언덕에 자리한 따뜻한 가족 휴양지, 그을린 목재로 지어진 이 주택으로 들어가 보세요.", "deep": {"lens": "화려한 무대를 설계하던 이들이 일상의 공간을 덜어냄으로써 얻은, 질감과 빛의 밀도로 구축한 정적인 드라마.", "why_now": "디지털 과잉 시대에 재료의 물성과 자연스러운 노후화를 받아들이는 주거 공간의 태도가 동시대적 휴식의 기준으로 부상하고 있다.", "mechanism": "기존의 복도식 평면을 유지하면서 천장고를 높이고 벽면과 일체화된 붙박이 가구를 배치하여 물리적 면적 이상의 개방감을 확보했다.", "sensory": "그을린 목재의 묵직한 어둠과 대조되는 따뜻한 베이지 톤의 실내, 그리고 시간이 지나며 빛깔이 변하는 황동과 대리석의 질감이 감각적 깊이를 더한다.", "transfer": "공간의 개방감을 위해 가구를 벽체와 동일한 마감재로 매립하고, 조명을 단순한 기능재가 아닌 공간의 분위기를 결정하는 독립된 오브제로 배치하는 연출을 적용한다.", "context": "안토니 지난자르와 애슐리 에반스는 크리에이티브 스튜디오 더 스퀘어드 디비전의 설립자로, 기존의 낡은 랜치 하우스가 가진 구조적 효율성을 보존하며 현대적 감각을 덧입히는 방식을 택했다.", "keywords": ["탄화목재", "랜치하우스", "미니멀리즘", "공간설계"], "evidence": "The house is a relatively low structure, engulfed in greenery and set underneath a mature tree. Its dark, charred timber façade makes it stand out from the foliage", "kind": "프로젝트", "depth": 3, "grounding": "full", "depth_reason": "기존 주택의 뼈대를 활용한 리노베이션 사례로서 공간의 효율적 구성과 재료의 선택이 명확하게 제시됨.", "sources": [], "findings": []}, "is_pick": true, "issue_date": "2026-11-22"}, {"id": "https://www.designboom.com/art/protect-learned-notice-jon-mccormacks-photography-patterns-natural-world-interview/", "title": "존 맥코맥의 시선, 자연의 기하학적 반복을 기록한 사진 탐구", "original_title": "‘we protect what we have learned to notice’: jon mccormack’s photographic exploration", "url": "https://www.designboom.com/art/protect-learned-notice-jon-mccormacks-photography-patterns-natural-world-interview/", "image_url": "https://www.designboom.com/wp-content/uploads/2026/11/jon-mccormack-patterns-photography-interview-designboom-03.jpg", "video_url": "", "has_video": false, "snippet": "사진작가 존 맥코맥(Jon McCormack)은 5년간 7개 대륙을 횡단하며 미세한 조류부터 남극의 빙하까지 자연에 내재된 반복적 패턴을 기록했다. 그는 댐아니(Damiani) 출판사를 통해 사진집 《패턴: 자연 세계의 예술(Patterns: Art of the Natural World)》을 선보이며, 서로 다른 규모의 자연 현상이 공유하는 기하학적 유사성을 조명한다.", "genre": "CONTEMPORARY ART", "source_name": "Designboom Art", "collected_at": "2026-11-22 00:20", "healed": true, "title_mt": "'우리는 우리가 알아차리도록 배운 것을 보호합니다': 존 맥코맥의 사진 탐구", "deep": {"lens": "거대한 지형과 미세한 유기체가 공유하는 기하학적 구조를 포착해 자연을 스스로 형태를 만드는 능동적 주체로 재정의한다.", "why_now": "인간 중심의 시각에서 벗어나 자연의 비인간적 조형성을 탐구하는 포스트휴먼 담론이 확장되는 흐름과 궤를 같이한다.", "mechanism": "동일한 장소와 피사체를 기상 조건에 관계없이 반복 촬영하는 제약을 설정해, 빛의 변화가 지형의 질감과 색채를 어떻게 변주하는지 드러낸다.", "sensory": "모래 언덕의 곡선과 빙하의 갈라진 틈, 미세 조류의 투명한 실리카 껍질이 만드는 비정형의 반복이 시각적 압도감을 선사한다.", "transfer": "콘티 연출 시 서로 다른 스케일의 피사체(예: 항공 촬영한 지형과 접사 촬영한 광물)를 동일한 프레임 구성으로 배치하여 시각적 등가성을 확보하는 기법을 제안한다.", "context": "본 프로젝트를 출간한 댐아니는 이반 매클렐런의 블랙 로데오 기록물 등 사회적 맥락이 짙은 사진집을 꾸준히 발행해 왔다. 존 맥코맥의 이번 작업은 인류학적 기록을 넘어 자연의 물리적 과정을 시각적 언어로 치환하는 데 집중한다.", "keywords": ["자연 패턴", "기하학적 구조", "지형 기록", "댐아니", "시각적 어휘"], "evidence": "‘The more I looked, the more I realized that nature has a remarkable visual vocabulary, and that learning to recognize it completely changes how you experience the world,’", "kind": "프로젝트", "depth": 4, "grounding": "full", "depth_reason": "자연의 패턴을 스케일과 무관한 시각 언어로 치환하여 사진적 방법론을 제시했으나, 과학적 원리에 대한 심층적 분석은 다소 제한적이다.", "sources": [{"n": 1, "type": "공식·1차", "title": "Damiani Books", "url": "https://www.damianibooks.com/en"}, {"n": 2, "type": "RE:COLLECTION 과거 기사", "title": "지워진 서부의 신화를 탈환하다, 흑인 로데오의 생생한 기록", "url": "https://www.dazeddigital.com/art-photography/article/71022/1/ivan-mcclellan-photography-black-rodeo-eight-seconds-legacy-motion?utm_source=Link&utm_medium=Link&utm_campaign=RSSFeed&utm_term=photos-that-capture-the-glamorous-world-of-black-rodeo"}, {"n": 3, "type": "RE:COLLECTION 과거 기사", "title": "이반 매클렐런이 포착한 블랙 로데오, 91장의 사진으로 다시 쓰는 서부의 기록", "url": "https://www.thisiscolossal.com/2026/11/ivan-mclellan-eight-seconds-legacy-in-motion/"}, {"n": 4, "type": "RE:COLLECTION 과거 기사", "title": "지워진 서부의 신화를 탈환하는 흑인 카우보이의 궤적, 이반 매클렐런", "url": "https://www.wallpaper.com/art/photography/eight-seconds-legacy-in-motion-book-by-ivan-mcclellan"}], "findings": []}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://www.wallpaper.com/art/film/inside-the-design-of-panem-the-dystopian-world-of-the-hunger-games", "title": "1970년대의 오만한 풍요로 구축한 헝거 게임의 디스토피아", "original_title": "Inside the design of Panem, the dystopian world of The Hunger Games", "url": "https://www.wallpaper.com/art/film/inside-the-design-of-panem-the-dystopian-world-of-the-hunger-games", "image_url": "https://cdn.mos.cms.futurecdn.net/AH7GfrLqwMgBf8aNvdMPBY-1920-80.png", "video_url": "", "has_video": false, "snippet": "영화 '헝거 게임: 수확의 새벽'의 프로덕션 디자이너 울리 하니쉬가 1970년대 미학과 베를린의 역사적 건축을 바탕으로 판엠의 세계를 재구조화한 과정을 공개했다. 거대하고 무거운 70년대의 조형 언어를 차용해 체제의 오만함과 매혹적인 기만을 시각화했다.", "genre": "CONTEMPORARY ART", "source_name": "Wallpaper*", "collected_at": "2026-11-22 00:20", "healed": true, "title_mt": "'헝거 게임'의 디스토피아 세계, 파넴의 디자인 속으로", "deep": {"lens": "1970년대의 풍요와 거대함을 권위주의 체제의 기만적 스펙터클로 치환한다.", "why_now": "가상의 미래 사회를 설계할 때 동시대의 역사적 건축 골조와 특정 시대의 정서적 레이어를 어떻게 이식하는지 보여주는 실전적 사례이기 때문이다.", "mechanism": "스페인 아스투리아스의 험준한 자연 지형과 독일의 거대한 폐철강 공장 인프라를 그대로 활용해 가공되지 않은 스케일을 확보했다. 여기에 70년대의 과장된 원색과 흰색 패브릭, 원형 소파를 배치해 진지한 대사와 부조화스러운 긴장을 만든다.", "sensory": "거대하고 무거운 콘크리트 덩어리, 비정상적으로 확장된 자동차와 공간의 스케일, 현기증을 유발하는 강렬한 원색의 대비가 감각을 압박한다.", "transfer": "공간이나 세트를 설계할 때 시대의 긍정적 지표 대신 당대 사회가 지닌 방종과 권위주의적 오만함을 물성과 컬러 팔레트로 번역해 콘티에 적용한다.", "context": "프로덕션 디자이너 울리 하니쉬는 이전작인 '퀸스 갬빗'과 '베를린 바빌론'에 이어 가상의 시대를 현실의 건축 유산과 결합하는 작업을 지속하고 있다.", "keywords": ["디스토피아", "프로덕션 디자인", "산업 유산", "공간 연출"], "evidence": "How do you reimagine the visual world of one of cinema’s biggest franchises though a 1970s lens?", "kind": "프로젝트", "depth": 4, "grounding": "full", "depth_reason": "구체적인 작업 과정과 시대적 미학의 변환 방식을 프로덕션 디자이너의 인터뷰를 통해 명확히 보여준다.", "sources": [{"n": 4, "type": "RE:COLLECTION 과거 기사", "title": "헝거 게임의 디스토피아, 1970년대 사이키델릭으로 재구성된 권위주의", "url": "https://www.architecturaldigest.com/story/the-hunger-games-sunrise-on-the-reaping-inside-the-psychedelic-1970s-inspired-dystopian-sets"}], "findings": [{"text": "프랜시스 로렌스 감독과 프로덕션 디자이너 울리 하니쉬는 헝거 게임의 프리퀄을 위해 1970년대 미학을 캐피톨의 시각적 언어로 채택했다.", "s": 4, "quote": "프랜시스 로렌스 감독과 프로덕션 디자이너 울리 하니쉬는 헝거 게임의 프리퀄을 위해 1970년대 미학을 캐피톨의 시각적 언어로 채택했다."}, {"text": "독일 뒤스부르크의 폐철강 공장을 활용해 12구역의 쇠락한 산업 풍경을 구현했다.", "s": 4, "quote": "독일 뒤스부르크의 폐철강 공장을 활용해 12구역의 쇠락한 산업 풍경을 구현했다."}]}, "is_pick": false, "issue_date": "2026-11-22"}, {"id": "https://minimalissimo.com/articles/cafeteria-mug-by-service-projects", "title": "서비스 프로젝트의 카페테리아 머그, 일상의 반복을 지탱하는 도자의 물성", "original_title": "Caféteria Mug by Service Projects", "url": "https://minimalissimo.com/articles/cafeteria-mug-by-service-projects", "image_url": "https://minimalissimo.com/api/media/file/cafeteria-mug-by-service-projects-featured-v20261117-1200x630.jpg", "video_url": "", "has_video": false, "snippet": "서비스 프로젝트(Service Projects)가 선보인 카페테리아 머그는 향수와 현대적 감각을 결합한 도자기 커피잔이다. 1,230도 고온 소성으로 내구성을 확보했으며, 적층 가능한 구조를 통해 보관의 효율성과 시각적 간결함을 동시에 구현했다.", "genre": "CONTEMPORARY ART", "source_name": "Minimalissimo", "collected_at": "2026-11-22 00:20", "healed": true, "title_mt": "Service Projects의 카페테리아 머그", "deep": {"lens": "형태의 기교를 덜어내고 적층이라는 구조적 반복을 통해 도자라는 재료가 가진 물리적 견고함을 일상의 리듬으로 치환한다.", "why_now": "디지털 피로가 누적된 환경에서 매일 손에 닿는 도구의 무게와 질감이 주는 감각적 안정감이 다시 주목받고 있다.", "mechanism": "1,230도 고온 소성으로 도자의 밀도를 높여 일상적인 사용에도 마모되지 않는 물리적 내구성을 확보했다.", "sensory": "매트한 표면의 건조한 질감과 적층 시 느껴지는 도자기 특유의 묵직한 마찰음이 공간의 정적을 환기한다.", "transfer": "공간 연출 시 동일한 기물을 반복적으로 쌓아 올려 수직적 정렬을 강조하는 오브제 배치 콘티에 활용한다.", "context": "서비스 프로젝트는 아를로 03을 통해 이중벽 스테인리스 스틸로 열적 분리 기능을 구현하는 등 재료의 물리적 반응을 기능으로 치환하는 설계를 지속해왔다. 이번 작업은 금속에서 도자로 매체를 옮겨 일상의 반복적 행위에 집중한다.", "keywords": ["도자", "적층 구조", "서비스 프로젝트", "물성"], "evidence": "This porcelain coffee cup is crafted with care and simplicity, fired at 1230 degrees for lasting durability.", "kind": "제품·오브제", "depth": 3, "grounding": "full", "depth_reason": "제품의 제작 방식과 구조적 특징을 명확히 설명하나, 기존 포트폴리오의 연장선에 있는 작업으로 혁신성보다는 완성도에 방점이 있다.", "sources": [{"n": 1, "type": "공식·1차", "title": "Caféteria Mug", "url": "https://service-projects.com/products/cafeteria-cup"}, {"n": 2, "type": "RE:COLLECTION 과거 기사", "title": "서비스 프로젝트의 아를로 03, 형태의 익숙함 뒤에 숨은 단열의 물성", "url": "https://minimalissimo.com/articles/the-arlo-03-by-service-projects"}], "findings": [{"text": "서비스 프로젝트의 포슬린 컬렉션은 제품에 따라 1280도에서 1440도 사이의 온도에서 소성된다.", "s": 1, "quote": "The Porcelain Collection is kiln-fired at varying temperatures between 1280°C and 1440°C, depending on the specific product."}]}, "is_pick": false, "issue_date": "2026-11-22"}];